114	function readFromCache<T extends object>(cachePath: string): T {
115	  try {
116	    return process.env.NX_CACHE_PROJECT_GRAPH !== 'false'
117	      ? readJsonFile<T>(cachePath)
118	      : ({} as T);
119	  } catch {
120	    return {} as T;
