133	function writeToCache<T extends object>(cachePath: string, data: T) {
134	  const maxAttempts = 5;
135	  for (let attempt = 0; attempt < maxAttempts; attempt++) {
136	    const unique = (Math.random().toString(16) + '00000000').slice(2, 10);
137	    const tempPath = `${cachePath}.${process.pid}.${unique}.tmp`;
138	    try {
139	      writeJsonFile(tempPath, data, { spaces: 0 });
140	      renameSync(tempPath, cachePath);
141	      return;
142	    } catch {
143	      try {
144	        unlinkSync(tempPath);
145	      } catch {}
146	    }
147	  }
148	}
