AE,YAAY,CAAC,CAAC;IAClE,MAAM,KAAK,GAAG,CAAC,CAAC,YAAY,CAC1B,YAAY,EACZ,OAAO,EACP,aAAa,EACb,SAAS,EACT,uBAAuB,CACxB,CAAC;IAEF,OAAO;QACL,KAAK;QACL,KAAK,EAAE,CAAC,CAAC,KAAK;QACd,YAAY,EAAE,CAAC,CAAC,YAAY;QAC5B,sBAAsB,EAAE,CAAC,CAAC,sBAAsB;KACjD,CAAC;AACJ,CAAC;AAED,SAAgB,+BAA+B,CAC7C,QAAoC;IAEpC,MAAM,GAAG,GAAG,EAAE,CAAC;IACf,MAAM,CAAC,IAAI,CAAC,QAAQ,IAAI,EAAE,CAAC,CAAC,OAAO,CAAC,CAAC,CAAC,EAAE,EAAE;QACxC,GAAG,CAAC,CAAC,CAAC,GAAG,QAAQ,CAAC,CAAC,CAAC,CAAC,SAAS,CAAC;IACjC,CAAC,CAAC,CAAC;IAEH,OAAO,GAAG,CAAC;AACb,CAAC;AAED,SAAS,oBAAoB,CAC3B,IAAO,EACP,WAAmB,EACnB,OAAY;IAEZ,MAAM,gBAAgB,GAAM,EAAE,GAAG,IAAI,EAAE,CAAC;IACxC,MAAM,CAAC,OAAO,CAAC,gBAAgB,CAAC,CAAC,OAAO,CAAC,CAAC,CAAC,IAAI,EAAE,KAAK,CAAC,EAAE,EAAE;QACzD,gBAAgB,CAAC,IAAI,CAAC;YACpB,OAAO,KAAK,KAAK,QAAQ;gBACvB,CAAC,CAAC,IAAA,mBAAW,EAAC,KAAK,EAAE;oBACjB,aAAa,EAAE,EAAE;oBACjB,WAAW,EAAE,OAAO,CAAC,IAAI;oBACzB,WAAW,EAAE,OAAO,CAAC,IAAI;oBACzB,OAAO,EAAE,EAAE,GAAG,OAAO,EAAE,IAAI,EAAE,WAAW,EAAE,EAAE,iBAAiB;iBAC9D,CAAC;gBACJ,CAAC,CAAC,KAAK,CAAC;IACd,CAAC,CAAC,CAAC;IACH,OAAO,gBAAgB,CAAC;AAC1B,CAAC;AAED;;;GAGG;AACH,SAAgB,gBAAgB,CAAC,YAAuC;IACtE,MAAM,MAAM,GAAG,IAAA,6BAAU,EAAC,EAAE,YAAY,EAAE,CAAC,CAAC;IAC5C,KAAK,MAAM,CAAC,GAAG,EAAE,IAAI,CAAC,IAAI,MAAM,CAAC,OAAO,CAAC,YAAY,CAAC,EAAE,CAAC;QACvD,IAAI,CAAC,GAAG,CAAC,QAAQ,CAAC,iBAAiB,CAAC,EAAE,CAAC;YACrC,MAAM,cAAc,GAAG,EAAE,CAAC;YAC1B,KAAK,MAAM,GAAG,IAAI,IAAI,EAAE,CAAC;gBACvB,cAAc,CAAC,IAAI,CACjB,GAAG,eAAe,CAAC,GAAG,EAAE,YAAY,EAAE,MAAM,EAAE,IAAI,GAAG,CAAC,CAAC,GAAG,CAAC,CAAC,CAAC,CAC9D,CAAC;YACJ,CAAC;YAED,YAAY,CAAC,GAAG,CAAC,GAAG,cAAc,CAAC;QACrC,CAAC;IACH,CAAC;IAED,KAAK,MAAM,GAAG,IAAI,MAAM,CAAC,IAAI,CAAC,YAAY,CAAC,EAAE,CAAC;QAC5C,IAAI,GAAG,CAAC,QAAQ,CAAC,iBAAiB,CAAC,EAAE,CAAC;YACpC,OAAO,YAAY,CAAC,GAAG,CAAC,CAAC;QAC3B,CAAC;IACH,CAAC;AACH,CAAC;AAED;;GAEG;AACH,SAAgB,eAAe,CAC7B,WAAmB,EACnB,YAAuC,EACvC,MAAoB,EACpB,OAAoB,IAAI,GAAG,EAAE;IAE7B,IAAI,IAAI,CAAC,GAAG,CAAC,WAAW,CAAC,EAAE,CAAC;QAC1B,OAAO,EAAE,CAAC;IACZ,CAAC;IACD,IAAI,CAAC,GAAG,CAAC,WAAW,CAAC,CAAC;IACtB,IAAI,WAAW,CAAC,QAAQ,CAAC,iBAAiB,CAAC,EAAE,CAAC;QAC5C,IAAI,MAAM,EAAE,GAAG,CAAC,WAAW,CAAC,EAAE,CAAC;YAC7B,OAAO,EAAE,CAAC;QACZ,CAAC;QACD,6DAA6D;QAC7D,OAAO,CACL,YAAY,CAAC,WAAW,CAAC,EAAE,OAAO,CAAC,CAAC,GAAG,EAAE,EAAE,CACzC,eAAe,CAAC,GAAG,EAAE,YAAY,EAAE,MAAM,EAAE,IAAI,CAAC,CACjD,IAAI,EAAE,CACR,CAAC;IACJ,CAAC;SAAM,CAAC;QACN,OAAO,CAAC,WAAW,CAAC,CAAC;IACvB,CAAC;AACH,CAAC;AAED,SAAS,YAAY,CACnB,OAAe,EACf,MAAc,EACd,aAAiC;IAEjC,IAAI,EAAE,GAAG,GAAG,OAAO,IAAI,MAAM,EAAE,CAAC;IAChC,IAAI,aAAa,EAAE,CAAC;QAClB,EAAE,IAAI,IAAI,aAAa,EAAE,CAAC;IAC5B,CAAC;IACD,OAAO,EAAE,CAAC;AACZ,CAAC","names":[],"sources":["/workspace/repo/packages/nx/src/tasks-runner/create-task-graph.ts"],"sourcesContent":["import { ProjectGraph, ProjectGraphProjectNode } from '../config/project-graph';\nimport { getDependencyConfigs, getOutputs, interpolate } from './utils';\nimport {\n  projectHasTarget,\n  projectHasTargetAndConfiguration,\n} from '../utils/project-graph-utils';\nimport { Task, TaskGraph } from '../config/task-graph';\nimport { TargetDefaults, TargetDependencies } from '../config/nx-json';\nimport { output } from '../utils/output';\nimport { TargetDependencyConfig } from '../config/workspace-json-project-json';\nimport { findCycles } from './task-graph-utils';\n\nconst DUMMY_TASK_TARGET = '__nx_dummy_task__';\n\nexport class ProcessTasks {\n  private readonly seen = new Set<string>();\n  readonly tasks: { [id: string]: Task } = {};\n  readonly dependencies: { [k: string]: string[] } = {};\n  readonly continuousDependencies: { [k: string]: string[] } = {};\n  private readonly allTargetNames: string[];\n\n  constructor(\n    private readonly extraTargetDependencies: TargetDependencies,\n    private readonly projectGraph: ProjectGraph\n  ) {\n    const allTargetNames = new Set<string>();\n    for (const projectName in projectGraph.nodes) {\n      const project = projectGraph.nodes[projectName];\n      for (const targetName in project.data.targets ?? {}) {\n        allTargetNames.add(targetName);\n      }\n    }\n    this.allTargetNames = Array.from(allTargetNames);\n  }\n\n  processTasks(\n    projectNames: string[],\n    targets: string[],\n    configuration: string,\n    overrides: Object,\n    excludeTaskDependencies: boolean\n  ): string[] {\n    for (const projectName of projectNames) {\n      for (const target of targets) {\n        const project = this.projectGraph.nodes[projectName];\n        if (targets.length === 1 || project.data.targets[target]) {\n          const resolvedConfiguration = this.resolveConfiguration(\n            project,\n            target,\n            configuration\n          );\n          const id = createTaskId(projectName, target, resolvedConfiguration);\n          const task = this.createTask(\n            id,\n            project,\n            target,\n            resolvedConfiguration,\n            overrides\n          );\n          this.tasks[task.id] = task;\n          this.dependencies[task.id] = [];\n          this.continuousDependencies[task.id] = [];\n        }\n      }\n    }\n\n    // used when excluding tasks\n    const initialTasks = { ...this.tasks };\n\n    for (const taskId of Object.keys(this.tasks)) {\n      const task = this.tasks[taskId];\n      this.processTask(task, task.target.project, configuration, overrides);\n    }\n\n    if (excludeTaskDependencies) {\n      for (let t of Object.keys(this.tasks)) {\n        if (!initialTasks[t]) {\n          delete this.tasks[t];\n          delete this.dependencies[t];\n          delete this.continuousDependencies[t];\n        }\n      }\n      for (let d of Object.keys(this.dependencies)) {\n        this.dependencies[d] = this.dependencies[d].filter(\n          (dd) => !!initialTasks[dd]\n        );\n      }\n      for (let d of Object.keys(this.continuousDependencies)) {\n        this.continuousDependencies[d] = this.continuousDependencies[d].filter(\n          (dd) => !!initialTasks[dd]\n        );\n      }\n    }\n\n    filterDummyTasks(this.dependencies);\n\n    for (const taskId of Object.keys(this.dependencies)) {\n      if (this.dependencies[taskId].length > 0) {\n        this.dependencies[taskId] = [\n          ...new Set(\n            this.dependencies[taskId].filter((d) => d !== taskId)\n          ).values(),\n        ];\n      }\n    }\n\n    filterDummyTasks(this.continuousDependencies);\n\n    for (const taskId of Object.keys(this.continuousDependencies)) {\n      if (this.continuousDependencies[taskId].length > 0) {\n        this.continuousDependencies[taskId] = [\n          ...new Set(\n            this.continuousDependencies[taskId].filter((d) => d !== taskId)\n          ).values(),\n        ];\n      }\n    }\n\n    return Object.keys(this.tasks).filter(\n      (d) =>\n        this.dependencies[d].length === 0 &&\n        this.continuousDependencies[d].length === 0\n    );\n  }\n\n  processTask(\n    task: Task,\n    projectUsedToDeriveDependencies: string,\n    configuration: string,\n    overrides: Object\n  ): void {\n    const seenKey = `${task.id}-${projectUsedToDeriveDependencies}`;\n    if (this.seen.has(seenKey)) {\n      return;\n    }\n    this.seen.add(seenKey);\n\n    const dependencyConfigs = getDependencyConfigs(\n      { project: task.target.project, target: task.target.target },\n      this.extraTargetDependencies,\n      this.projectGraph,\n      this.allTargetNames\n    );\n    for (const dependencyConfig of dependencyConfigs) {\n      const taskOverrides =\n        dependencyConfig.params === 'forward'\n          ? overrides\n          : { __overrides_unparsed__: [] };\n      if (dependencyConfig.projects) {\n        this.processTasksForMultipleProjects(\n          dependencyConfig,\n          configuration,\n          task,\n          taskOverrides,\n          overrides\n        );\n      } else if (dependencyConfig.dependencies) {\n        this.processTasksForDependencies(\n          projectUsedToDeriveDependencies,\n          dependencyConfig,\n          configuration,\n          task,\n          taskOverrides,\n          overrides\n        );\n      } else {\n        this.processTasksForSingleProject(\n          task,\n          task.target.project,\n          dependencyConfig,\n          configuration,\n          taskOverrides,\n          overrides\n        );\n      }\n    }\n  }\n\n  private processTasksForMultipleProjects(\n    dependencyConfig: TargetDependencyConfig,\n    configuration: string,\n    task: Task,\n    taskOverrides: Object | { __overrides_unparsed__: any[] },\n    overrides: Object\n  ) {\n    if (dependencyConfig.projects.length === 0) {\n      output.warn({\n        title: `\\`dependsOn\\` is misconfigured for ${task.target.project}:${task.target.target}`,\n        bodyLines: [\n          `Project patterns \"${dependencyConfig.projects}\" does not match any projects.`,\n        ],\n      });\n    }\n    for (const projectName of dependencyConfig.projects) {\n      this.processTasksForSingleProject(\n        task,\n        projectName,\n        dependencyConfig,\n        configuration,\n        taskOverrides,\n        overrides\n      );\n    }\n  }\n\n  private processTasksForSingleProject(\n    task: Task,\n    projectName: string,\n    dependencyConfig: TargetDependencyConfig,\n    configuration: string,\n    taskOverrides: Object | { __overrides_unparsed__: any[] },\n    overrides: Object\n  ) {\n    const selfProject = this.projectGraph.nodes[\n      projectName\n    ] as ProjectGraphProjectNode;\n\n    if (projectHasTarget(selfProject, dependencyConfig.target)) {\n      const resolvedConfiguration = this.resolveConfiguration(\n        selfProject,\n        dependencyConfig.target,\n        configuration\n      );\n      const selfTaskId = createTaskId(\n        selfProject.name,\n        dependencyConfig.target,\n        resolvedConfiguration\n      );\n      if (!this.tasks[selfTaskId]) {\n        const newTask = this.createTask(\n          selfTaskId,\n          selfProject,\n          dependencyConfig.target,\n          resolvedConfiguration,\n          taskOve