,sBAAsB,CAAC,mBAA6B;IAC3D,MAAM,IAAI,KAAK,CACb,iDAAiD,mBAAmB,CAAC,IAAI,CACvE,IAAI,CACL,GAAG,CACL,CAAC;AACJ,CAAC;AAED,SAAgB,YAAY,CAC1B,IAAqB,EACrB,MAAc,EACd,uBAA+B,EAC/B,OAAiB;IAEjB,IAAA,sBAAS,EACP,YAAY,IAAI,CAAC,cAAc,IAAI,uBAAuB,EAAE,EAC5D;QACE,GAAG,MAAM;QACT,UAAU,EAAE,MAAM,CAAC,UAAU;KAC9B,EACD;QACE,IAAI,EAAE,UAAU;QAChB,MAAM,EAAE,IAAI,CAAC,cAAc;QAC3B,MAAM,EAAE,uBAAuB;QAC/B,OAAO;KACR,CACF,CAAC;AACJ,CAAC;AAEM,KAAK,UAAU,QAAQ,CAAC,IAA0B;IACvD,OAAO,IAAA,4BAAY,EAAC,IAAI,CAAC,OAAO,EAAE,KAAK,IAAI,EAAE;QAC3C,MAAM,mBAAmB,GAAG,IAAA,0BAAU,GAAE,CAAC;QACzC,MAAM,YAAY,GAAG,MAAM,IAAA,uCAAuB,GAAE,CAAC;QACrD,MAAM,sBAAsB,GAC1B,IAAA,yDAAyC,EAAC,YAAY,CAAC,CAAC;QAC1D,MAAM,IAAI,GAAG,MAAM,wBAAwB,CACzC,IAAI,EACJ,UAAU,EACV,sBAAsB,CACvB,CAAC;QAEF,MAAM,EACJ,uBAAuB,EACvB,MAAM,EACN,qBAAqB,EACrB,sBAAsB,EAAE,EACtB,OAAO,EACP,MAAM,EACN,CAAC,cAAc,CAAC,EAAE,UAAU,EAC5B,CAAC,yBAAyB,CAAC,EAAE,kBAAkB,GAChD,GACF,GAAG,IAAA,yCAAuB,EACzB,IAAI,CAAC,cAAc,EACnB,IAAI,CAAC,aAAa,EAClB,8BAAa,EACb,sBAAsB,CAAC,QAAQ,CAChC,CAAC;QAEF,IAAI,UAAU,EAAE,CAAC;YACf,eAAM,CAAC,IAAI,CACT;gBACE,GAAG,kBAAS,KAAK,IAAI,CAAC,cAAc,IAAI,uBAAuB,gBAAgB;gBAC/E,GAAG,UAAU,EAAE;aAChB,CAAC,IAAI,CAAC,IAAI,CAAC,CACb,CAAC;QACJ,CAAC;QACD,IAAI,CAAC,IAAI,CAAC,KAAK,IAAI,CAAC,IAAI,CAAC,IAAI,EAAE,CAAC;YAC9B,eAAM,CAAC,IAAI,CACT,iBAAiB,IAAI,CAAC,cAAc,IAAI,uBAAuB,EAAE,CAClE,CAAC;QACJ,CAAC;QAED,IAAI,IAAI,CAAC,IAAI,EAAE,CAAC;YACd,YAAY,CAAC,IAAI,EAAE,MAAM,EAAE,uBAAuB,EAAE,OAAO,CAAC,CAAC;YAC7D,OAAO,CAAC,CAAC;QACX,CAAC;QAED,MAAM,GAAG,GAAG,IAAA,aAAM,GAAE,CAAC;QAErB,MAAM,YAAY,GAAG,MAAM,IAAA,mCAA0B,EACnD,IAAI,CAAC,gBAAgB,EACrB,IAAI,CAAC,cAAc,EACnB,uBAAuB,EACvB,sBAAsB,EACtB,mBAAmB,EACnB,MAAM,EACN,IAAI,CAAC,WAAW,EAChB,IAAA,4DAA2B,EACzB,GAAG,EACH,8BAAa,EACb,sBAAsB,EACtB,mBAAmB,CACpB,EACD,IAAA,eAAQ,EAAC,8BAAa,EAAE,GAAG,CAAC,EAC5B,IAAI,CAAC,OAAO,CACb,CAAC;QAEF,IACE,IAAA,yCAAuB,EACrB,IAAI,CAAC,cAAc,EACnB,uBAAuB,EACvB,8BAAa,EACb,sBAAsB,CAAC,QAAQ,CAChC,CAAC,aAAa,EACf,CAAC;YACD,MAAM,IAAI,GAAG,IAAI,aAAM,CACrB,8BAAa,EACb,IAAI,CAAC,OAAO,EACZ,eAAe,IAAI,CAAC,cAAc,IAAI,uBAAuB,GAAG,CACjE,CAAC;YACF,MAAM,cAAc,GAAG,qBAAqB,EAAE,CAAC;YAE/C,mEAAmE;YACnE,IAAI,uBAAuB,KAAK,QAAQ,IAAI,CAAC,kBAAkB,EAAE,CAAC;gBAChE,IAAI,CAAC,KAAK,CAAC,eAAe,EAAE,EAAE,CAAC,CAAC;gBAChC,IAAI,CAAC,KAAK,CAAC,eAAe,EAAE,EAAE,CAAC,CAAC;YAClC,CAAC;YAED,MAAM,IAAI,GAAG,MAAM,cAAc,CAAC,IAAI,EAAE,YAAY,CAAC,CAAC;YACtD,IAAI,CAAC,IAAI,EAAE,CAAC;YAEZ,MAAM,OAAO,GAAG,IAAI,CAAC,WAAW,EAAE,CAAC;YAEnC,IAAI,CAAC,IAAI,CAAC,KAAK,EAAE,CAAC;gBAChB,YAAY,CAAC,OAAO,CAAC,CAAC;YACxB,CAAC;YACD,IAAI,CAAC,IAAI,CAAC,MAAM,EAAE,CAAC;gBACjB,IAAA,mBAAY,EAAC,8BAAa,EAAE,OAAO,CAAC,CAAC;gBACrC,IAAI,IAAI,EAAE,CAAC;oBACT,MAAM,IAAI,EAAE,CAAC;gBACf,CAAC;YACH,CAAC;iBAAM,CAAC;gBACN,eAAM,CAAC,IAAI,CAAC,uDAAuD,CAAC,CAAC;YACvE,CAAC;QACH,CAAC;aAAM,CAAC;YACN,OAAO,CAAC,sBAAsB,CAAC,CAAC;YAChC,OAAO,CAAC,2CAAa,6BAA6B,EAAC,CAAC,CAAC,QAAQ,CAC3D,8BAAa,EACb;gBACE,GAAG,IAAI;gBACP,gBAAgB,EAAE,YAAY;aAC/B,EACD,sBAAsB,CAAC,QAAQ,EAC/B,IAAI,CAAC,OAAO,CACb,CAAC;QACJ,CAAC;IACH,CAAC,CAAC,CAAC;AACL,CAAC","names":[],"sources":["/workspace/repo/packages/nx/src/command-line/generate/generate.ts"],"sourcesContent":["import * as chalk from 'chalk';\nimport { prompt } from 'enquirer';\nimport { relative } from 'path';\n\nimport { readNxJson } from '../../config/configuration';\nimport { ProjectsConfigurations } from '../../config/workspace-json-project-json';\nimport { FileChange, flushChanges, FsTree } from '../../generators/tree';\nimport {\n  createProjectGraphAsync,\n  readProjectsConfigurationFromProjectGraph,\n} from '../../project-graph/project-graph';\nimport { logger, NX_PREFIX } from '../../utils/logger';\nimport {\n  combineOptionsForGenerator,\n  Options,\n  Schema,\n} from '../../utils/params';\nimport { handleErrors } from '../../utils/handle-errors';\nimport { getLocalWorkspacePlugins } from '../../utils/plugins/local-plugins';\nimport { printHelp } from '../../utils/print-help';\nimport { workspaceRoot } from '../../utils/workspace-root';\nimport { calculateDefaultProjectName } from '../../config/calculate-default-project-name';\nimport { findInstalledPlugins } from '../../utils/plugins/installed-plugins';\nimport { getGeneratorInformation } from './generator-utils';\nimport { getCwd } from '../../utils/path';\n\nexport interface GenerateOptions {\n  collectionName: string;\n  generatorName: string;\n  generatorOptions: Options;\n  help: boolean;\n  dryRun: boolean;\n  interactive: boolean;\n  defaults: boolean;\n  quiet: boolean;\n}\n\nexport function printChanges(fileChanges: FileChange[]) {\n  fileChanges.forEach((f) => {\n    if (f.type === 'CREATE') {\n      console.log(`${chalk.green('CREATE')} ${f.path}`);\n    } else if (f.type === 'UPDATE') {\n      console.log(`${chalk.white('UPDATE')} ${f.path}`);\n    } else if (f.type === 'DELETE') {\n      console.log(`${chalk.yellow('DELETE')} ${f.path}`);\n    }\n  });\n}\n\nasync function promptForCollection(\n  generatorName: string,\n  interactive: boolean,\n  projectsConfiguration: ProjectsConfigurations\n): Promise<string> {\n  const localPlugins = await getLocalWorkspacePlugins(\n    projectsConfiguration,\n    readNxJson()\n  );\n\n  const installedCollections = Array.from(\n    new Set(findInstalledPlugins().map((x) => x.name))\n  );\n\n  const choicesMap = new Set<string>();\n\n  const deprecatedChoices = new Set<string>();\n\n  for (const collectionName of installedCollections) {\n    try {\n      const {\n        resolvedCollectionName,\n        normalizedGeneratorName,\n        generatorConfiguration: { ['x-deprecated']: deprecated, hidden },\n      } = getGeneratorInformation(\n        collectionName,\n        generatorName,\n        workspaceRoot,\n        projectsConfiguration.projects\n      );\n      if (hidden) {\n        continue;\n      }\n      if (deprecated) {\n        deprecatedChoices.add(\n          `${resolvedCollectionName}:${normalizedGeneratorName}`\n        );\n      } else {\n        choicesMap.add(`${resolvedCollectionName}:${normalizedGeneratorName}`);\n      }\n    } catch {}\n  }\n\n  const choicesFromLocalPlugins: {\n    name: string;\n    message: string;\n    value: string;\n  }[] = [];\n  for (const [name] of localPlugins) {\n    try {\n      const {\n        resolvedCollectionName,\n        normalizedGeneratorName,\n        generatorConfiguration: { ['x-deprecated']: deprecated, hidden },\n      } = getGeneratorInformation(\n        name,\n        generatorName,\n        workspaceRoot,\n        projectsConfiguration.projects\n      );\n      if (hidden) {\n        continue;\n      }\n      const value = `${resolvedCollectionName}:${normalizedGeneratorName}`;\n      if (!choicesMap.has(value)) {\n        if (deprecated) {\n          deprecatedChoices.add(value);\n        } else {\n          choicesFromLocalPlugins.push({\n            name: value,\n            message: chalk.bold(value),\n            value,\n          });\n        }\n      }\n    } catch {}\n  }\n  if (choicesFromLocalPlugins.length) {\n    choicesFromLocalPlugins[choicesFromLocalPlugins.length - 1].message += '\\n';\n  }\n  const choices = (\n    choicesFromLocalPlugins as (\n      | string\n      | {\n          name: string;\n          message: string;\n          value: string;\n        }\n    )[]\n  ).concat(...choicesMap);\n  if (choices.length === 1) {\n    return typeof choices[0] === 'string' ? choices[0] : choices[0].value;\n  } else if (!interactive && choices.length > 1) {\n    throwInvalidInvocation(Array.from(choicesMap));\n  } else if (interactive && choices.length > 1) {\n    const noneOfTheAbove = `\\nNone of the above`;\n    choices.push(noneOfTheAbove);\n    let { generator, customCollection } = await prompt<{\n      generator: string;\n      customCollection?: string;\n    }>([\n      {\n        name: 'generator',\n        message: `Which generator would you like to use?`,\n        type: 'autocomplete',\n        // enquirer's typings are incorrect here... It supports (string | Choice)[], but is typed as (string[] | Choice[])\n        choices: choices as string[],\n      },\n      {\n        name: 'customCollection',\n        type: 'input',\n        message: `Which collection would you like to use?`,\n        skip: function () {\n          // Skip this question if the user did not answer None of the above\n          return this.state.answers.generator !== noneOfTheAbove;\n        },\n        validate: function (value) {\n          if (this.skipped) {\n            return true;\n          }\n          try {\n            getGeneratorInformation(\n              value,\n              generatorName,\n              workspaceRoot,\n              projectsConfiguration.projects\n            );\n            return true;\n          } catch {\n            logger.error(`\\nCould not find ${value}:${generatorName}`);\n            return false;\n          }\n        },\n      },\n    ]);\n    return customCollection\n      ? `${customCollection}:${generatorName}`\n      : generator;\n  } else if (deprecatedChoices.size > 0) {\n    throw new Error(\n      [\n        `All installed generators named \"${generatorName}\" are deprecated. To run one, provide its full \\`collection:generator\\` id.`,\n        [...deprecatedChoices].map((x) => `  - ${x}`),\n      ].join('\\n')\n    );\n  } else {\n    throw new Error(`Could not find any generators named \"${generatorName}\"`);\n  }\n}\n\nexport function parseGeneratorString(value: string): {\n  collection?: string;\n  generator: string;\n} {\n  const separatorIndex = value.lastIndexOf(':');\n\n  if (separatorIndex > 0) {\n    return {\n      collection: value.slice(0, separatorIndex),\n      generator: value.slice(separatorIndex + 1),\n    };\n  } else {\n    return {\n      generator: value,\n    };\n  }\n}\n\nasync function convertToGenerateOptions(\n  generatorOptions: { [p: string]: any },\n  mode: 'generate' | 'new',\n  projectsConfiguration?: ProjectsConfigurations\n): Promise<GenerateOptions> {\n  let collectionName: string | null = null;\n  let generatorName: string | null = null;\n  const interactive = generatorOptions.interactive as boolean;\n\n  if (mode === 'generate') {\n    const generatorDescriptor = generatorOptions['generator'] as string;\n    const { collection, generator } = parseGeneratorString(generatorDescriptor);\n\n    if (collection) {\n      collectionName = collection;\n      generatorName = generator;\n    } else {\n      const generatorString = await promptForCollection(\n        generatorDescriptor,\n        interactive,\n        projectsConfiguration\n      );\n      const parsedGeneratorString = parseGeneratorString(generatorString);\n      collectionName = parsedGeneratorString.collection;\n      generatorName = parsedGeneratorString.generator;\n    }\n  } else {\n    collectionName = generatorOptions.collection as string;\n    generatorName = 'new';\n  }\n\n  const res = {\n    collectionName,\n    generatorName,\n    generatorOptions,\n    help: generatorOptions.help as boolean,\n    dryRun: generatorOptions.dryRun as boolean,\n    interactive,\n    defaults: generatorOptions.defaults as boolean,\n    quiet: generatorOptions.quiet,\n  };\n\n  delete generatorOptions.d;\n  delete generatorOptions.dryRun;\n  delete generatorOptions['dry-run'];\n  delete generatorOptions.interactive;\n  delete generatorOptions.help;\n  delete generatorOptions.collection;\n  delete generatorOptions.verbose;\n  delete generatorOptions.generator;\n  delete generatorOptions['--'];\n  delete generatorOptions['$0'];\n  delete generatorOptions.quiet;\n\n  return res;\n}\n\nfunction throwInvalidInvocation(availableGenerators: string[]) {\n  throw new Error(\n    `Specify the generator name (e.g., nx generate ${availableGenerators.join(\n      ', '\n    )})`\n  );\n}\n\nexport function printGenHelp(\n  opts: GenerateOptions,\n  schema: Schema,\n  normalizedGeneratorName: string,\n  aliases: string[]\n) {\n  printHelp(\n    `generate ${opts.collectionName}:${normalizedGeneratorName}`,\n    {\n      ...schema,\n      properties: schema.properties,\n    },\n    {\n      mode: 'generate',\n      plugin: opts.collectionName,\n      entity: normalizedGeneratorName,\n      aliases,\n    }\n  );\n}\n\nexport async function generate(args: { [k: string]: any }) {\n  return handleErrors(args.verbose, async () => {\n    const nxJsonConfiguration = readNxJson();\n    const projectGraph = await createProjectGraphAsync();\n    const projectsConfigurations =\n      readProjectsConfigurationFromProjectGraph(projectGraph);\n    const opts = await convertToGenerateOptions(\n      args,\n      'generate',\n      projectsConfigurations\n    );\n\n    const {\n      normalizedGeneratorName,\n      schema,\n      implementationFactory,\n      generatorConfiguration: {\n        aliases,\n        hidden,\n        ['x-deprecated']: deprecated,\n        ['x-use-standalone-layout']: isStandalonePreset,\n      },\n    } = getGeneratorInformation(\n      opts.collectionName,\n      opts.generatorName,\n      workspaceRoot,\n      projectsConfigurations.projects\n    );\n\n    if (deprecated) {\n      logger.warn(\n        [\n          `${NX_PREFIX}: ${opts.collectionName}:${normalizedGeneratorName} is deprecated`,\n          `${deprecated}`,\n        ].join('\\n')\n      );\n    }\n    if (!opts.quiet && !opts.help) {\n      logger.info(\n        `NX Generating ${opts.collectionName}:${normalizedGeneratorName}`\n      );\n    }\n\n    if (opts.help) {\n      printGenHelp(opts, schema, normalizedGeneratorName, aliases);\n      return 0;\n    }\n\n    const cwd = getCwd();\n\n    const combinedOpts = await combineOptionsForGenerator(\n      opts.generatorOptions,\n      opts.collectionName,\n      normalizedGeneratorName,\n      projectsConfigurations,\n      nxJsonConfiguration,\n      schema,\n      opts.interactive,\n      calculateDefaultProjectName(\n        cwd,\n        workspaceRoot,\n        projectsConfigurations,\n        nxJsonConfiguration\n      ),\n      relative(workspaceRoot, cwd),\n      args.verbose\n    );\n\n    if (\n      getGeneratorInformation(\n