CAAC;IAC7D,CAAC;IAED,OAAO,YAAY,CAAC;AACtB,CAAC;AAED,SAAS,gBAAgB;IACvB,IAAI,CAAC;QACH,MAAM,YAAY,GAAG,IAAA,gCAAmB,GAAE,CAAC;QAC3C,IAAI,YAAY,EAAE,CAAC;YACjB,OAAO,IAAA,wBAAY,EAAC,YAAY,EAAE,EAAE,cAAc,EAAE,IAAI,EAAE,CAAC,CAAC;QAC9D,CAAC;IACH,CAAC;IAAC,OAAO,CAAC,EAAE,CAAC;QACX,OAAO,EAAE,CAAC;IACZ,CAAC;AACH,CAAC;AAEM,KAAK,UAAU,oBAAoB,CACxC,KAAmB,EACnB,OAAyB,EACzB,OAA8B,EAC9B,SAAkC;IAElC,MAAM,OAAO,GAAyD,EAAE,CAAC;IACzE,MAAM,MAAM,GAA0B,EAAE,CAAC;IAEzC,wBAAW,CAAC,IAAI,CAAC,sBAAsB,CAAC,CAAC;IACzC,IAAI,OAAuB,CAAC;IAC5B,MAAM,iBAAiB,GAAG,IAAI,GAAG,EAAU,CAAC;IAE5C,SAAS,aAAa;QACpB,IAAI,CAAC,OAAO,IAAI,iBAAiB,CAAC,IAAI,KAAK,CAAC,EAAE,CAAC;YAC7C,OAAO;QACT,CAAC;QAED,IAAI,iBAAiB,CAAC,IAAI,KAAK,CAAC,EAAE,CAAC;YACjC,OAAO,CAAC,UAAU,CAChB,kCACE,iBAAiB,CAAC,MAAM,EAAE,CAAC,IAAI,EAAE,CAAC,KACpC,EAAE,CACH,CAAC;QACJ,CAAC;aAAM,IAAI,OAAO,CAAC,GAAG,CAAC,kBAAkB,KAAK,MAAM,EAAE,CAAC;YACrD,OAAO,CAAC,UAAU,CAChB;gBACE,kCAAkC,iBAAiB,CAAC,IAAI,UAAU;gBAClE,GAAG,KAAK,CAAC,IAAI,CAAC,iBAAiB,CAAC,CAAC,GAAG,CAAC,CAAC,CAAC,EAAE,EAAE,CAAC,OAAO,CAAC,EAAE,CAAC;aACxD,CAAC,IAAI,CAAC,IAAI,CAAC,CACb,CAAC;QACJ,CAAC;aAAM,CAAC;YACN,OAAO,CAAC,UAAU,CAChB,kCAAkC,iBAAiB,CAAC,IAAI,UAAU,CACnE,CAAC;QACJ,CAAC;IACH,CAAC;IAED,OAAO,GAAG,IAAI,gCAAc,CAC1B,kCAAkC,OAAO,CAAC,MAAM,UAAU,CAC3D,CAAC;IAEF,MAAM,QAAQ,GAAG,OAAO,CAAC,GAAG,CAAC,KAAK,EAAE,MAAM,EAAE,EAAE;QAC5C,IAAI,MAAM,CAAC,cAAc,EAAE,CAAC;YAC1B,wBAAW,CAAC,IAAI,CAAC,GAAG,MAAM,CAAC,IAAI,yBAAyB,CAAC,CAAC;YAC1D,iBAAiB,CAAC,GAAG,CAAC,MAAM,CAAC,IAAI,CAAC,CAAC;YACnC,IAAI,CAAC;gBACH,MAAM,QAAQ,GAAG,MAAM,MAAM,CAAC,cAAc,CAAC,KAAK,EAAE,OAAO,CAAC,CAAC;gBAC7D,OAAO,CAAC,IAAI,CAAC,EAAE,QAAQ,EAAE,UAAU,EAAE,MAAM,CAAC,IAAI,EAAE,CAAC,CAAC;YACtD,CAAC;YAAC,OAAO,CAAC,EAAE,CAAC;gBACX,MAAM,CAAC,IAAI,CAAC,IAAI,iCAAmB,CAAC,CAAC,EAAE,MAAM,CAAC,IAAI,CAAC,CAAC,CAAC;YACvD,CAAC;oBAAS,CAAC;gBACT,iBAAiB,CAAC,MAAM,CAAC,MAAM,CAAC,IAAI,CAAC,CAAC;gBACtC,aAAa,EAAE,CAAC;gBAChB,wBAAW,CAAC,IAAI,CAAC,GAAG,MAAM,CAAC,IAAI,uBAAuB,CAAC,CAAC;gBACxD,wBAAW,CAAC,OAAO,CACjB,GAAG,MAAM,CAAC,IAAI,iBAAiB,EAC/B,GAAG,MAAM,CAAC,IAAI,yBAAyB,EACvC,GAAG,MAAM,CAAC,IAAI,uBAAuB,CACtC,CAAC;YACJ,CAAC;QACH,CAAC;IACH,CAAC,CAAC,CAAC;IAEH,MAAM,OAAO,CAAC,GAAG,CAAC,QAAQ,CAAC,CAAC;IAE5B,OAAO,EAAE,OAAO,EAAE,CAAC;IAEnB,KAAK,MAAM,EAAE,QAAQ,EAAE,gBAAgB,EAAE,UAAU,EAAE,IAAI,OAAO,EAAE,CAAC;QACjE,KAAK,MAAM,OAAO,IAAI,gBAAgB,EAAE,CAAC;YACvC,MAAM,oBAAoB,GACxB,KAAK,CAAC,KAAK,CAAC,OAAO,CAAC,EAAE,IAAI,CAAC;YAC7B,IAAI,oBAAoB,EAAE,CAAC;gBACzB,oBAAoB,CAAC,QAAQ,GAAG,IAAA,2CAAa,EAC3C,SAAS,CAAC,OAAO,CAAC,EAClB,CAAC,IAAI,EAAE,UAAU,CAAC,EAClB,UAAU,EACV,gBAAgB,CAAC,OAAO,CAAC,CAAC,QAAQ,EAClC,oBAAoB,CAAC,QAAQ,CAC9B,CAAC;YACJ,CAAC;QACH,CAAC;IACH,CAAC;IAED,wBAAW,CAAC,IAAI,CAAC,oBAAoB,CAAC,CAAC;IACvC,wBAAW,CAAC,OAAO,CACjB,gBAAgB,EAChB,sBAAsB,EACtB,oBAAoB,CACrB,CAAC;IAEF,OAAO,EAAE,MAAM,EAAE,KAAK,EAAE,CAAC;AAC3B,CAAC","names":[],"sources":["/workspace/repo/packages/nx/src/project-graph/build-project-graph.ts"],"sourcesContent":["import { workspaceRoot } from '../utils/workspace-root';\nimport { join } from 'path';\nimport { performance } from 'perf_hooks';\nimport { assertWorkspaceValidity } from '../utils/assert-workspace-validity';\nimport { FileData } from './file-utils';\nimport {\n  CachedFileData,\n  createProjectFileMapCache,\n  extractCachedFileData,\n  FileMapCache,\n  shouldRecomputeWholeGraph,\n} from './nx-deps-cache';\nimport { applyImplicitDependencies } from './utils/implicit-project-dependencies';\nimport { normalizeProjectNodes } from './utils/normalize-project-nodes';\nimport type { LoadedNxPlugin } from './plugins/loaded-nx-plugin';\nimport {\n  CreateDependenciesContext,\n  CreateMetadataContext,\n  ProjectsMetadata,\n} from './plugins';\nimport { getRootTsConfigPath } from '../plugins/js/utils/typescript';\nimport {\n  FileMap,\n  ProjectGraph,\n  ProjectGraphExternalNode,\n} from '../config/project-graph';\nimport { readJsonFile } from '../utils/fileutils';\nimport { NxJsonConfiguration } from '../config/nx-json';\nimport { ProjectGraphBuilder } from './project-graph-builder';\nimport { ProjectConfiguration } from '../config/workspace-json-project-json';\nimport { readNxJson } from '../config/configuration';\nimport { existsSync } from 'fs';\nimport { PackageJson } from '../utils/package-json';\nimport { NxWorkspaceFilesExternals } from '../native';\nimport {\n  AggregateProjectGraphError,\n  CreateMetadataError,\n  isAggregateProjectGraphError,\n  isWorkspaceValidityError,\n  ProcessDependenciesError,\n  WorkspaceValidityError,\n} from './error-types';\nimport {\n  ConfigurationSourceMaps,\n  mergeMetadata,\n} from './utils/project-configuration-utils';\nimport { DelayedSpinner } from '../utils/delayed-spinner';\n\nlet storedFileMap: FileMap | null = null;\nlet storedAllWorkspaceFiles: FileData[] | null = null;\nlet storedRustReferences: NxWorkspaceFilesExternals | null = null;\n\nexport function getFileMap(): {\n  fileMap: FileMap;\n  allWorkspaceFiles: FileData[];\n  rustReferences: NxWorkspaceFilesExternals | null;\n} {\n  if (!!storedFileMap) {\n    return {\n      fileMap: storedFileMap,\n      allWorkspaceFiles: storedAllWorkspaceFiles,\n      rustReferences: storedRustReferences,\n    };\n  } else {\n    return {\n      fileMap: {\n        nonProjectFiles: [],\n        projectFileMap: {},\n      },\n      allWorkspaceFiles: [],\n      rustReferences: null,\n    };\n  }\n}\n\nexport function hydrateFileMap(\n  fileMap: FileMap,\n  allWorkspaceFiles: FileData[],\n  rustReferences: NxWorkspaceFilesExternals\n) {\n  storedFileMap = fileMap;\n  storedAllWorkspaceFiles = allWorkspaceFiles;\n  storedRustReferences = rustReferences;\n}\n\nexport async function buildProjectGraphUsingProjectFileMap(\n  projectRootMap: Record<string, ProjectConfiguration>,\n  externalNodes: Record<string, ProjectGraphExternalNode>,\n  fileMap: FileMap,\n  allWorkspaceFiles: FileData[],\n  rustReferences: NxWorkspaceFilesExternals,\n  fileMapCache: FileMapCache | null,\n  plugins: LoadedNxPlugin[],\n  sourceMap: ConfigurationSourceMaps\n): Promise<{\n  projectGraph: ProjectGraph;\n  projectFileMapCache: FileMapCache;\n}> {\n  storedFileMap = fileMap;\n  storedAllWorkspaceFiles = allWorkspaceFiles;\n  storedRustReferences = rustReferences;\n\n  const projects: Record<string, ProjectConfiguration> = {};\n  for (const root in projectRootMap) {\n    const project = projectRootMap[root];\n    projects[project.name] = project;\n  }\n\n  const errors: Array<\n    CreateMetadataError | ProcessDependenciesError | WorkspaceValidityError\n  > = [];\n\n  const nxJson = readNxJson();\n  const projectGraphVersion = '6.0';\n  try {\n    assertWorkspaceValidity(projects, nxJson);\n  } catch (e) {\n    if (isWorkspaceValidityError(e)) {\n      errors.push(e);\n    }\n  }\n  const packageJsonDeps = readCombinedDeps();\n  const rootTsConfig = readRootTsConfig();\n\n  let filesToProcess: FileMap;\n  let cachedFileData: CachedFileData;\n  const useCacheData =\n    fileMapCache &&\n    !shouldRecomputeWholeGraph(\n      fileMapCache,\n      packageJsonDeps,\n      projects,\n      nxJson,\n      rootTsConfig\n    );\n  if (useCacheData) {\n    const fromCache = extractCachedFileData(fileMap, fileMapCache);\n    filesToProcess = fromCache.filesToProcess;\n    cachedFileData = fromCache.cachedFileData;\n  } else {\n    filesToProcess = fileMap;\n    cachedFileData = {\n      nonProjectFiles: {},\n      projectFileMap: {},\n    };\n  }\n\n  let projectGraph: ProjectGraph;\n  let projectFileMapCache: FileMapCache;\n  try {\n    const context = createContext(\n      projects,\n      nxJson,\n      externalNodes,\n      fileMap,\n      filesToProcess\n    );\n    projectGraph = await buildProjectGraphUsingContext(\n      externalNodes,\n      context,\n      cachedFileData,\n      projectGraphVersion,\n      plugins,\n      sourceMap\n    );\n    projectFileMapCache = createProjectFileMapCache(\n      nxJson,\n      packageJsonDeps,\n      fileMap,\n      rootTsConfig\n    );\n  } catch (e) {\n    // we need to include the workspace validity errors in the final error\n    if (isAggregateProjectGraphError(e)) {\n      errors.push(...e.errors);\n      throw new AggregateProjectGraphError(errors, e.partialProjectGraph);\n    } else {\n      throw e;\n    }\n  }\n\n  if (errors.length > 0) {\n    throw new AggregateProjectGraphError(errors, projectGraph);\n  }\n\n  return {\n    projectGraph,\n    projectFileMapCache,\n  };\n}\n\nfunction readCombinedDeps() {\n  const installationPackageJsonPath = join(\n    workspaceRoot,\n    '.nx',\n    'installation',\n    'package.json'\n  );\n  const installationPackageJson: Partial<PackageJson> = existsSync(\n    installationPackageJsonPath\n  )\n    ? readJsonFile(installationPackageJsonPath)\n    : {};\n  const rootPackageJsonPath = join(workspaceRoot, 'package.json');\n  const rootPackageJson: Partial<PackageJson> = existsSync(rootPackageJsonPath)\n    ? readJsonFile(rootPackageJsonPath)\n    : {};\n  return {\n    ...rootPackageJson.dependencies,\n    ...rootPackageJson.devDependencies,\n    ...installationPackageJson.dependencies,\n    ...installationPackageJson.devDependencies,\n  };\n}\n\nasync function buildProjectGraphUsingContext(\n  knownExternalNodes: Record<string, ProjectGraphExternalNode>,\n  ctx: CreateDependenciesContext,\n  cachedFileData: CachedFileData,\n  projectGraphVersion: string,\n  plugins: LoadedNxPlugin[],\n  sourceMap: ConfigurationSourceMaps\n) {\n  const builder = new ProjectGraphBuilder(null, ctx.fileMap.projectFileMap);\n  builder.setVersion(projectGraphVersion);\n  for (const node in knownExternalNodes) {\n    builder.addExternalNode(knownExternalNodes[node]);\n  }\n\n  await normalizeProjectNodes(ctx, builder);\n  const initProjectGraph = builder.getUpdatedProjectGraph();\n\n  let updatedGraph;\n  let error: AggregateProjectGraphError;\n  try {\n    updatedGraph = await updateProjectGraphWithPlugins(\n      ctx,\n      initProjectGraph,\n      plugins,\n      sourceMap\n    );\n  } catch (e) {\n    if (isAggregateProjectGraphError(e)) {\n      updatedGraph = e.partialProjectGraph;\n      error = e;\n    } else {\n      throw e;\n    }\n  }\n\n  const updatedBuilder = new ProjectGraphBuilder(\n    updatedGraph,\n    ctx.fileMap.projectFileMap\n  );\n  for (const proj of Object.keys(cachedFileData.projectFileMap)) {\n    for (const f of ctx.fileMap.projectFileMap[proj] || []) {\n      const cached = cachedFileData.projectFileMap[proj][f.file];\n      if (cached && cached.deps) {\n        f.deps = [...cached.deps];\n      }\n    }\n  }\n  for (const file of ctx.fileMap.nonProjectFiles) {\n    const cached = cachedFileData.nonProjectFiles[file.file];\n    if (cached?.deps) {\n      file.deps = [...cached.deps];\n    }\n  }\n\n  applyImplicitDependencies(ctx.projects, updatedBuilder);\n\n  const finalGraph = updatedBuilder.getUpdatedProjectGraph();\n\n  if (!error) {\n    return finalGraph;\n  } else {\n    throw new AggregateProjectGraphError(error.errors, finalGraph);\n  }\n}\n\nfunction createContext(\n  projects: Record<string, ProjectConfiguration>,\n  nxJson: NxJsonConfiguration,\n  externalNodes: Record<string, ProjectGraphExternalNode>,\n  fileMap: FileMap,\n  filesToProcess: FileMap\n): CreateDependenciesContext {\n  return {\n    nxJsonConfiguration: nxJson,\n    projects,\n    externalNodes,\n    workspaceRoot,\n    fileMap,\n    filesToProcess,\n  };\n}\n\nasync function updateProjectGraphWithPlugins(\n  context: CreateDependenciesContext,\n  initProjectGraph: ProjectGraph,\n  plugins: LoadedNxPlugin[],\n  sourceMap: ConfigurationSourceMaps\n) {\n  let graph = initProjectGraph;\n  const errors: Array<ProcessDependenciesError | CreateMetadataError> = [];\n\n  const builder = new ProjectGraphBuilder(\n    graph,\n    context.fileMap.projectFileMap,\n    context.fileMap.nonProjectFiles\n  );\n\n  const createDependencyPlugins = plugins.filter(\n    (plugin) => plugin.createDependencies\n  );\n  performance.mark('createDependencies:start');\n\n  let spinner: DelayedSpinner;\n  const inProgressPlugins = new Set<string>();\n\n  function updateSpinner() {\n    if (!spinner || inProgressPlugins.size === 0) {\n      return;\n    }\n\n    if (inProgressPlugins.size === 1) {\n      spinner.setMessage(\n        `Creating project graph dependencies with ${\n          inProgressPlugins.values().next().value\n        }`\n      );\n    } else if (process.env.NX_VERBOSE_LOGGING === 'true') {\n      spinner.setMessage(\n        [\n          `Creating project graph dependencies with ${inProgressPlugins.size} plugins`,\n          ...Array.from(inProgressPlugins).map((p) => `  - ${p}`),\n        ].join('\\n')\n      );\n    } else {\n      spinner.setMessage(\n        `Creating project graph dependencies with ${inProgressPlugins.size} plugins`\n      );\n    }\n  }\n\n  spinner = new DelayedSpinner(\n    `Creating project graph dependencies with ${plugins.length} plugins`\n  );\n\n  await Promise.all(\n    createDependencyPlugins.map(async (plugin) => {\n      performance.mark(`${plugin.name}:createDependencies - start`);\n      inProgressPlugins.add(plugin.name);\n      try {\n        const dependencies = await plugin\n          .createDependencies({\n            ...context,\n          })\n          .finally(() => {\n            inProgressPlugins.delete(plugin.name);\n            updateSpinner();\n          });\n\n        for (const dep of dependencies) {\n          builder.addDependency(\n            dep.source,\n            dep.target,\n            dep.type,\n            'sourceFile' in dep ? dep.sourceFile : null\n          );\n        }\n      } catch (cause) {\n        errors.push(\n          new ProcessDependenciesError(plugin.name, {\n            cause,\n          })\n        );\n      }\n\n      performance.mark(`${plugin.name}:createDependencies - end`);\n      performance.measure(\n        `${plugin.name}:createDependencies`,\n        `${plugin.name}:createDependencies - start`,\n        `${plugin.name}:createDependencies - end`\n      );\n    })\n  );\n  performance.mark('createDependencies:end');\n  perform