EAAE,CAAC;gCAC5B,OAAO,IAAI,CAAC;4BACd,CAAC;iCAAM,CAAC;gCACN,OAAO;oCACL,OAAO,EAAE,IAAI,CAAC,KAAK;oCACnB,IAAI,EAAE,IAAI,CAAC,KAAK;iCACjB,CAAC;4BACJ,CAAC;wBACH,CAAC,CAAC,CAAC;gBACL,QAAQ,CAAC,KAAK,GAAG,wBAAwB,CAAC;YAC5C,CAAC;iBAAM,IAAI,CAAC,CAAC,IAAI,KAAK,SAAS,EAAE,CAAC;gBAChC,QAAQ,CAAC,IAAI,GAAG,SAAS,CAAC;YAC5B,CAAC;iBAAM,CAAC;gBACN,QAAQ,CAAC,IAAI,GAAG,OAAO,CAAC;YAC1B,CAAC;YACD,OAAO,CAAC,IAAI,CAAC,QAAQ,CAAC,CAAC;QACzB,CAAC;IACH,CAAC,CAAC,CAAC;IAEH,OAAO,OAAO,CAAC;AACjB,CAAC;AAED,KAAK,UAAU,eAAe,CAC5B,IAAa,EACb,MAAc,EACd,sBAA8C;IAE9C,OAAO,MAAM,CACX,2CAAa,UAAU,EAAC,CACzB;SACE,MAAM,CAAC,mBAAmB,CAAC,IAAI,EAAE,MAAM,EAAE,sBAAsB,CAAC,CAAC;SACjE,IAAI,CAAC,CAAC,MAAM,EAAE,EAAE,CAAC,CAAC,EAAE,GAAG,IAAI,EAAE,GAAG,MAAM,EAAE,CAAC,CAAC;SAC1C,KAAK,CAAC,CAAC,CAAC,EAAE,EAAE;QACX,OAAO,CAAC,KAAK,CAAC,CAAC,CAAC,CAAC;QACjB,OAAO,CAAC,IAAI,CAAC,CAAC,CAAC,CAAC;IAClB,CAAC,CAAC,CAAC;AACP,CAAC;AAED,SAAS,qBAAqB,CAC5B,QAAgB,EAChB,MAAc;IAEd,IAAI,QAAQ,IAAI,MAAM,CAAC,UAAU,EAAE,CAAC;QAClC,OAAO;YACL,IAAI,EAAE,QAAQ;YACd,WAAW,EAAE,MAAM,CAAC,UAAU,CAAC,QAAQ,CAAC;SACzC,CAAC;IACJ,CAAC;IACD,MAAM,KAAK,GAAG,MAAM,CAAC,OAAO,CAAC,MAAM,CAAC,UAAU,CAAC,CAAC,IAAI,CAClD,CAAC,CAAC,CAAC,EAAE,CAAC,CAAC,EAAE,EAAE,CACT,CAAC,CAAC,KAAK,KAAK,QAAQ;QACpB,CAAC,KAAK,CAAC,OAAO,CAAC,CAAC,CAAC,OAAO,CAAC,IAAI,CAAC,CAAC,OAAO,CAAC,QAAQ,CAAC,QAAQ,CAAC,CAAC,CAC7D,CAAC;IACF,IAAI,KAAK,EAAE,CAAC;QACV,MAAM,CAAC,IAAI,EAAE,WAAW,CAAC,GAAG,KAAK,CAAC;QAClC,OAAO,EAAE,IAAI,EAAE,WAAW,EAAE,CAAC;IAC/B,CAAC;IACD,OAAO,IAAI,CAAC;AACd,CAAC;AAED,SAAS,KAAK;IACZ,OAAO,CAAC,CAAC,OAAO,CAAC,MAAM,CAAC,KAAK,IAAI,OAAO,CAAC,GAAG,CAAC,IAAI,CAAC,KAAK,MAAM,CAAC;AAChE,CAAC;AAED;;;GAGG;AACH,SAAS,sBAAsB,CAAC,KAAK;IACnC,IAAI,SAAS,KAAK,OAAO,KAAK,EAAE,CAAC;QAC/B,OAAO,IAAI,CAAC;IACd,CAAC;IAED,IAAI,QAAQ,KAAK,OAAO,KAAK,IAAI,YAAY,CAAC,IAAI,CAAC,KAAK,CAAC,EAAE,CAAC;QAC1D,OAAO,IAAI,CAAC;IACd,CAAC;IAED,OAAO,KAAK,CAAC;AACf,CAAC;AAED;;;GAGG;AACH,SAAS,qBAAqB,CAAC,KAAK;IAClC,8BAA8B;IAC9B,IAAI,SAAS,KAAK,OAAO,KAAK,EAAE,CAAC;QAC/B,OAAO,KAAK,CAAC;IACf,CAAC;IAED,OAAO,CAAC,KAAK,CAAC,CAAC,KAAK,CAAC,CAAC;AACxB,CAAC","names":[],"sources":["/workspace/repo/packages/nx/src/utils/params.ts"],"sourcesContent":["import { logger } from './logger';\nimport type { NxJsonConfiguration } from '../config/nx-json';\nimport type {\n  ProjectsConfigurations,\n  TargetConfiguration,\n} from '../config/workspace-json-project-json';\n\ntype PropertyDescription = {\n  type?: string | string[];\n  required?: string[];\n  enum?: string[];\n  properties?: Properties;\n  oneOf?: PropertyDescription[];\n  anyOf?: PropertyDescription[];\n  allOf?: PropertyDescription[];\n  items?: any;\n  alias?: string;\n  aliases?: string[];\n  description?: string;\n  format?: string;\n  visible?: boolean;\n  hidden?: boolean;\n  default?:\n    | string\n    | number\n    | boolean\n    | string[]\n    | { [key: string]: string | number | boolean | string[] };\n  $ref?: string;\n  $default?:\n    | { $source: 'argv'; index: number }\n    | { $source: 'projectName' }\n    | { $source: 'unparsed' }\n    | { $source: 'workingDirectory' };\n  additionalProperties?: boolean | PropertyDescription;\n  const?: any;\n  'x-prompt'?:\n    | string\n    | { message: string; type: string; items?: any[]; multiselect?: boolean };\n  'x-deprecated'?: boolean | string;\n  'x-dropdown'?: 'projects';\n  'x-priority'?: 'important' | 'internal';\n\n  // Numbers Only\n  multipleOf?: number;\n  minimum?: number;\n  exclusiveMinimum?: number;\n  maximum?: number;\n  exclusiveMaximum?: number;\n\n  // Strings Only\n  pattern?: string;\n  minLength?: number;\n  maxLength?: number;\n\n  // Objects Only\n  patternProperties?: {\n    [pattern: string]: PropertyDescription;\n  };\n};\n\ntype Properties = {\n  [p: string]: PropertyDescription;\n};\nexport type Schema = {\n  properties: Properties;\n  required?: string[];\n  anyOf?: Partial<Schema>[];\n  oneOf?: Partial<Schema>[];\n  description?: string;\n  definitions?: Properties;\n  additionalProperties?: boolean | PropertyDescription;\n  examples?: { command: string; description?: string }[];\n  patternProperties?: {\n    [pattern: string]: PropertyDescription;\n  };\n};\n\nexport type Unmatched = {\n  name: string;\n  possible: string[];\n};\n\nexport type Options = {\n  '--'?: Unmatched[];\n  [k: string]: string | number | boolean | string[] | Unmatched[] | undefined;\n};\n\nfunction camelCase(input: string): string {\n  if (input.indexOf('-') > 1) {\n    return input\n      .toLowerCase()\n      .replace(/-(.)/g, (match, group1) => group1.toUpperCase());\n  } else {\n    return input;\n  }\n}\n\nexport function convertToCamelCase(\n  parsed: { [k: string]: any },\n  schema: Schema\n): Options {\n  return Object.keys(parsed).reduce((m, c) => {\n    if (schema.properties[camelCase(c)]) {\n      return { ...m, [camelCase(c)]: parsed[c] };\n    } else {\n      return { ...m, [c]: parsed[c] };\n    }\n  }, {});\n}\n\n/**\n * Coerces (and replaces) options identified as 'boolean' or 'number' in the Schema\n *\n * @param opts The options to check\n * @param schema The schema definition with types to check against\n *\n */\nexport function coerceTypesInOptions(opts: Options, schema: Schema): Options {\n  Object.keys(opts).forEach((k) => {\n    const prop = findSchemaForProperty(k, schema);\n\n    opts[k] = coerceType(prop?.description, opts[k]);\n  });\n  return opts;\n}\n\nfunction coerceType(prop: PropertyDescription | undefined, value: any) {\n  if (!prop) return value;\n  if (typeof value !== 'string' && value !== undefined) return value;\n\n  if (prop.oneOf) {\n    for (let i = 0; i < prop.oneOf.length; ++i) {\n      const coerced = coerceType(prop.oneOf[i], value);\n      if (coerced !== value) {\n        return coerced;\n      }\n    }\n    return value;\n  } else if (Array.isArray(prop.type)) {\n    for (let i = 0; i < prop.type.length; ++i) {\n      const coerced = coerceType({ type: prop.type[i] }, value);\n      if (coerced !== value) {\n        return coerced;\n      }\n    }\n    return value;\n  } else if (\n    normalizedPrimitiveType(prop.type) == 'boolean' &&\n    isConvertibleToBoolean(value)\n  ) {\n    return value === true || value == 'true';\n  } else if (\n    normalizedPrimitiveType(prop.type) == 'number' &&\n    isConvertibleToNumber(value)\n  ) {\n    return Number(value);\n  } else if (prop.type == 'array') {\n    return value.split(',').map((v) => coerceType(prop.items, v));\n  } else {\n    return value;\n  }\n}\n\n/**\n * Converts any options passed in with short aliases to their full names if found\n * Unmatched options are added to opts['--']\n *\n * @param opts The options passed in by the user\n * @param schema The schema definition to check against\n */\nexport function convertAliases(\n  opts: Options,\n  schema: Schema,\n  excludeUnmatched: boolean\n): Options {\n  return Object.keys(opts).reduce((acc, k) => {\n    const prop = findSchemaForProperty(k, schema);\n    if (prop) {\n      acc[prop.name] = opts[k];\n    } else if (excludeUnmatched) {\n      if (!acc['--']) {\n        acc['--'] = [];\n      }\n      acc['--'].push({\n        name: k,\n        possible: [],\n      });\n    } else {\n      acc[k] = opts[k];\n    }\n    return acc;\n  }, {});\n}\n\nexport class SchemaError {\n  constructor(public readonly message: string) {}\n}\n\nexport function validateOptsAgainstSchema(\n  opts: { [k: string]: any },\n  schema: Schema\n) {\n  validateObject(opts, schema, schema.definitions || {});\n}\n\nexport function validateObject(\n  opts: { [p: string]: any },\n  schema: Schema | PropertyDescription,\n  definitions: Properties\n) {\n  if (schema.anyOf) {\n    const errors: Error[] = [];\n    for (const s of schema.anyOf) {\n      try {\n        validateObject(opts, s, definitions);\n      } catch (e) {\n        errors.push(e);\n      }\n    }\n    if (errors.length === schema.anyOf.length) {\n      throw new Error(\n        `Options did not match schema. Please fix any of the following errors:\\n${errors\n          .map((e) => ' - ' + e.message)\n          .join('\\n')}`\n      );\n    }\n  }\n  if (schema.oneOf) {\n    const matches: Array<PropertyDescription> = [];\n    const errors: Array<Error> = [];\n    for (const propertyDescription of schema.oneOf) {\n      try {\n        validateObject(opts, propertyDescription, definitions);\n        matches.push(propertyDescription);\n      } catch (error) {\n        errors.push(error);\n      }\n    }\n    // If the options matched none of the oneOf property descriptions\n    if (matches.length === 0) {\n      throw new Error(\n        `Options did not match schema: ${JSON.stringify(\n          opts,\n          null,\n          2\n        )}.\\nPlease fix 1 of the following errors:\\n${errors\n          .map((e) => ' - ' + e.message)\n          .join('\\n')}`\n      );\n    }\n    // If the options matched none of the oneOf property descriptions\n    if (matches.length > 1) {\n      throw new Error(\n        `Options did not match schema: ${JSON.stringify(\n          opts,\n          null,\n          2\n        )}.\\nShould only match one of \\n${matches\n          .map((m) => ' - ' + JSON.stringify(m))\n          .join('\\n')}`\n      );\n    }\n  }\n\n  (schema.required ?? []).forEach((p) => {\n    if (opts[p] === undefined) {\n      throw new SchemaError(`Required property '${p}' is missing`);\n    }\n  });\n\n  if (\n    schema.additionalProperties !== undefined &&\n    schema.additionalProperties !== true\n  ) {\n    Object.keys(opts).find((p) => {\n      if (\n        Object.keys(schema.properties ?? {}).indexOf(p) === -1 &&\n        (!schema.patternProperties ||\n          !Object.keys(schema.patternProperties).some((pattern) =>\n            new RegExp(pattern).test(p)\n          ))\n      ) {\n        if (p === '_') {\n          throw new SchemaError(\n            `Schema does not support positional arguments. Argument '${opts[p]}' found`\n          );\n        } else if (schema.additionalProperties === false) {\n          throw new SchemaError(`'${p}' is not found in sch