CnB,CAAC,CAAC,KAAK,CAAC,CAAC,CAAC,KAAK,GAAG,IAAI,KAAK,CAAC,CAAC,CAAC,KAAK,GAAG,CAAC,EACvC,CAAC;YACD,OAAO,GAAG,GAAG,KAAK,KAAK,GAAG,CAAC;QAC7B,CAAC;QACD,OAAO,GAAG,CAAC;IACb,CAAC;SAAM,IAAI,GAAG,CAAC,QAAQ,CAAC,GAAG,CAAC,IAAI,CAAC,CAAC,GAAG,CAAC,CAAC,CAAC,KAAK,GAAG,IAAI,GAAG,CAAC,CAAC,CAAC,KAAK,GAAG,CAAC,EAAE,CAAC;QACpE,OAAO,IAAI,GAAG,GAAG,CAAC;IACpB,CAAC;SAAM,CAAC;QACN,OAAO,GAAG,CAAC;IACb,CAAC;AACH,CAAC","names":[],"sources":["/workspace/repo/packages/nx/src/executors/run-commands/run-commands.impl.ts"],"sourcesContent":["import * as yargsParser from 'yargs-parser';\nimport { ExecutorContext } from '../../config/misc-interfaces';\nimport { isTuiEnabled } from '../../tasks-runner/is-tui-enabled';\nimport { PseudoTerminal } from '../../tasks-runner/pseudo-terminal';\nimport { NoopChildProcess } from '../../tasks-runner/running-tasks/noop-child-process';\nimport {\n  ParallelRunningTasks,\n  runSingleCommandWithPseudoTerminal,\n  SeriallyRunningTasks,\n} from './running-tasks';\n\nexport const LARGE_BUFFER = 1024 * 1000000;\nexport type Json = {\n  [k: string]: any;\n};\n\nexport interface RunCommandsCommandOptions {\n  command: string;\n  forwardAllArgs?: boolean;\n  /**\n   * description was added to allow users to document their commands inline,\n   * it is not intended to be used as part of the execution of the command.\n   */\n  description?: string;\n  prefix?: string;\n  prefixColor?: string;\n  color?: string;\n  bgColor?: string;\n}\n\nexport interface RunCommandsOptions extends Json {\n  command?: string | string[];\n  commands?: Array<RunCommandsCommandOptions | string>;\n  color?: boolean;\n  parallel?: boolean;\n  readyWhen?: string | string[];\n  cwd?: string;\n  env?: Record<string, string>;\n  forwardAllArgs?: boolean; // default is true\n  args?: string | string[];\n  envFile?: string;\n  __unparsed__: string[];\n  usePty?: boolean;\n  streamOutput?: boolean;\n  tty?: boolean;\n}\n\nconst propKeys = [\n  'command',\n  'commands',\n  'color',\n  'no-color',